test('each action needs actual postrevision currentproposal scope candidate and nonsimulation provenance before currentG2',()=>{
 const {envelope,c}=nativeSyntheticFixture();
 for(const intent of ['authorize_merge','authorize_deploy']){
  const action=e=>e.events.find(x=>x.kind==='user'&&x.payload.intent===intent);
  const cases=[
   e=>{e.events=e.events.filter(x=>!(x.kind==='user'&&x.payload.intent===intent));},
   e=>action(e).payload.scope={...action(e).payload.scope,paths:['src/wrong.ts']},
   e=>action(e).payload.proposal_hash='0'.repeat(64),
   e=>action(e).payload.reply_to='0'.repeat(64),
   e=>action(e).payload.candidate_sha='0'.repeat(40),
   e=>action(e).payload.verification_level='simulation',
   e=>action(e).payload.intent='continue',
   e=>action(e).payload.quote=' ',
   e=>action(e).payload.source_ref='',
   e=>{const old=action(e),i=e.events.indexOf(old);e.events.splice(i,1);e.events.unshift(old);},
   e=>{const late=action(e),i=e.events.indexOf(late);e.events.splice(i,1);e.events.splice(e.events.length-1,0,late);},
  ];
  for(const mutate of cases){const bad=structuredClone(envelope);mutate(bad);let seq=c.nativeAuthority.anchor.events;for(const event of bad.events)event.seq=++seq;rehashSynthetic(bad);assert.throws(()=>validateNativeIntent(bad,c),'must reject '+intent);}
 }
});

